  `business_status` varchar(255) DEFAULT NULL,
  `latest_adjustment_request_id` bigint DEFAULT NULL,
  `adjusted_total_amount` double DEFAULT NULL,
  `adjustment_required` tinyint(1) NOT NULL DEFAULT '0',
